const image=(src,caption)=>`<figure><img src="assets/${src}" alt="${caption}" loading="lazy"><figcaption>${caption}</figcaption></figure>`;
const section=(title,body)=>`<section class="detail-content"><h2>${title}</h2><div>${body}</div></section>`;
export const projects={
 'two-sided-life':{title:'双面人生：<br>解码双相情感障碍。',label:'SHORT FILM / 2025',lead:'从自己提出的主题出发，和团队一起把它变成一部心理科普短片。',meta:[['项目角色','选题提出 · 全部拍摄 · 共同制作'],['团队','六人团队'],['成果','心理科普短视频征集活动一等奖']],body:`<div class="detail-art"><div class="project-visual film-art"><span class="film-label">A SHORT FILM ABOUT BIPOLAR DISORDER</span><span class="film-title">双面<i>人生</i></span><div class="film-sun"></div><span class="film-award">2025 · 一等奖</span><small>作品集项目题图 · 非成片截图</small></div></div>${section('主题与表达','<p>我提出“解码双相情感障碍”这一创作主题，希望通过短视频这一形式，让观众愿意停下来了解相关心理健康知识。具体情节与内容解读将在成片整理后补充。</p>')}${section('我做了什么','<h3>独立包揽拍摄，也参与镜头前后的协作。</h3><p>除出镜外，我参与了项目的主要创作环节，包括主题、脚本、后期与团队协调，其中全部拍摄由我独立完成。作品的最终呈现是六人团队共同创作的结果。</p>')}${section('奖项与署名','<p>广东省教育厅主办的 2025 年“5.25”大学生心理健康月系列活动——“光影筑心，赋能成长”心理科普短视频征集活动：一等奖。</p><p>团队成员：许润仪、叶烨、严穗敏、李安澜、曾菲、钟俊裕。<br>指导老师：叶昶。<br>所在学院：华南农业大学资源环境学院。</p>')}${section('成片','<p>完整视频与封面待整理接入。这里先展示项目背景与已确认分工，不用其他视频代替成片。</p>')}`},
liuyi:{title:'留忆。<br>给回忆，一座小岛。',label:'PERSONAL PRODUCT / AI COLLABORATION',lead:'和朋友出去玩的照片，不该只停留在相册里。我想把它们做成能翻开的书，收藏在心里的小岛。',meta:[['我的角色','产品构思 · 需求梳理 · 体验判断'],['协作方式','AI 辅助画面与代码实现'],['当前阶段','线上初版 + 本地迭代原型']],body:`${image('island.webp','手绘小岛是回忆的入口，小屋承载一本作品。')}${section('从生活出发','<p>旅行和朋友的照片越积越多，我希望把一次出行的照片整理成一本 zine，像收起一本纸质小册子一样，放进属于这段回忆的小屋。</p><p>从选择小岛，到进入小屋、选图、自动排版、修改和翻阅，产品的功能与体验想法由我构思，AI 帮助梳理需求、生成适合的画面与动画，并实现原型。</p>')}${section('一条完整流程','<h3>选照片 → 自动排版 → 编辑预览 → 导出。</h3><p>本地阶段 A 原型已打通照片选择、三种排版风格、文字与照片编辑、锁页、历史恢复，以及阅读、家庭打印和打印店三类 PDF 导出。</p><button class="detail-action" data-demo="island">翻一本示例册子 ↗</button><p>作品集中的翻书使用预置照片，只演示阅读感受，不代表在这里运行完整编辑器。</p>')}${section('设计中的取舍','<p>小岛与小屋负责让回忆容易被找到，编辑器负责把作品做完。先在本地验证选图、排版和导出，再逐步考虑多人共享，控制个人项目的实现范围。</p><p>自动排版通过模板和照片比例组织，不需要把每次排版描述为一次在线 AI 生成。</p>')}${section('目前做到哪里','<p>线上链接是初版；本地版本有进一步完善的流程，两者不完全相同。登录、朋友共享、跨设备同步与自动歌词尚未接通。当前本地存储不等于云备份，真机及实体打印仍待进一步验证。</p><a class="detail-action" href="https://liuyi-memory-islands.yansimay78.chatgpt.site/" target="_blank" rel="noopener">访问留忆线上初版 ↗</a>')}`},
'daily-ops':{title:'日常工作台。<br>把重复，交给工具。',label:'BSH / PERSONAL WORKFLOW TOOL',lead:'原来的工作并不难，却重复、繁琐，且要求精确。我把 SOP 中共通的步骤，整理成一个自己使用的工作台。',meta:[['使用场景','培训考试 · 线索匹配 · 进度跟踪'],['我的贡献','流程拆解 · 规则定义 · 核对迭代'],['状态','个人自用 · AI 辅助实现']],body:`${image('ops-01.webp','工作台整体界面。截图使用合成数据。')}${section('问题在哪里','<p>每次拿到源表，都要重新匹配名单、选择统计维度、输出汇总，再整理群通知。列名变化、员工号录入差异和多张名单，让简单操作变得费时且需要高度专注。</p>')}${section('拆出共同动作','<h3>对齐 → 汇总 → 通报。</h3><p>把原本分散的工作整理成考试数据跟踪、线索匹配和进度跟踪三个入口。现在我主要负责提取源数据、确认配置并核对最终结果，重复处理由工具执行。</p><button class="detail-action" data-demo="ops">用示例数据看一次流程 ↗</button>')}${image('ops-03.webp','员工号异常核对：将两个来源的编号并排展示，方便人工复核。')}${section('一个真实发现','<h3>13 条异常，是匹配问题。</h3><p>一次考试核对最初显示 13 人未完成。逐条检查后发现是员工号少录一位或位数对调；核对修正后，240 人全部完成。这里解决的是识别错误，不能把它写成“工具提升了考试完成率”。</p><p>员工号优先匹配；姓名唯一时提供兜底并单独列出，遇到重名保留人工核对，不替使用者猜测。</p>')}${image('ops-02.webp','汇总报表：按分部、名单类别和业务维度查看结果。')}${section('让输出可用','<p>自动识别列名但允许手动修正；支持同一工作簿中的多张名单；根据结果生成通报文案，减少重复抄写。源表只读，计算在本地浏览器完成。</p><p>效率价值体现在减少匹配与汇总步骤，最终结果仍由我核对。它是个人自用工具，尚不宣称团队推广或业务规模化收益。</p>')}${image('ops-04.webp','群通知文案随结果生成。截图不包含真实员工信息。')}`}
};

projects['mcd-internship']={title:'麦当劳。<br>让内容连接现场。',label:'INTERNSHIP / MCDONALD’S',lead:'在广州领导力学院，把培训活动中的想法，变成看得见、用得上的内容。',meta:[['实习时间','2025.06 — 2026.05'],['公司','麦当劳 · 广州领导力学院'],['岗位','学习与训练部实习生']],layout:'internship',left:`<section><small>01 / 日常工作</small><h2>从前期准备，<br>到现场记录。</h2><p>参与学习与训练相关内容制作和活动支持，制作宣传物料与游戏内容，并记录活动过程。</p></section><section><small>02 / 活动案例</small><h2>冠军俱乐部，<br>成长交流日。</h2><p>围绕菁英管培生交流活动，制作前期宣传海报；参考已有游戏玩法，结合麦当劳企业背景改编内容，制作游戏 PPT。</p><p>活动中负责拍摄；活动后筛选照片，制作朋友圈九宫格，把交流中的时刻留下来。</p><p class="case-note">游戏 PPT 原文件暂未找回；右侧展示已提供的原始作品。</p></section><section><small>03 / 视觉内容</small><h2>也让荣誉被看见。</h2><p>课程荣誉榜物料展示。通过信息层级、人物与品牌插画组织课程表彰内容。</p></section>`,right:`${image('mcd-champion.webp','冠军俱乐部 · 成长交流日｜活动宣传海报')}<figure class="case-video"><video controls playsinline preload="metadata" poster="${new URL('assets/mcd-video-poster.webp',import.meta.url).href}" aria-label="冠军俱乐部成长交流日活动视频"><source src="${new URL('assets/mcd-event.mp4',import.meta.url).href}" type="video/mp4">当前浏览器不支持视频播放。</video><figcaption>冠军俱乐部 · 成长交流日｜活动影像</figcaption></figure>${image('mcd-honors.webp','6—8 月 SLT 课程荣誉榜｜原始视觉物料')}`};
projects['bsh-internship']={title:'BSH 博西家电。<br>让日常更有条理。',label:'INTERNSHIP / BSH',lead:'在数据跟进和导购管理的重复工作里，发现问题，也尝试做出自己的解决工具。',meta:[['实习时间','2026.06 — 2026.08'],['公司','BSH 博西家电'],['岗位','市场部实习生 · 导购管理']],layout:'internship',left:`<section><small>01 / 工作内容</small><h2>跟进培训，<br>核对每一份数据。</h2><p>参与培训与考试进度跟进、数据统计、名单与线索匹配，并借助 QuickBI 跟进相关线索。</p></section><section><small>02 / 自用工具</small><h2>把 SOP，<br>变成一个工作台。</h2><p>把反复执行的匹配、汇总和通报整理为明确流程，借助 AI 实现个人自用工作台。现在主要负责提取源数据、确认处理规则，并核对最终输出。</p><button class="detail-action" data-demo="ops">体验一遍示例流程 ↗</button></section><section><small>03 / 核对与判断</small><h2>13 条异常，<br>逐条查清楚。</h2><p>一次核对中发现 13 条员工号录入差异；人工核实并修正匹配后，确认 240 人全部完成考试。这是纠正匹配错误，不是提升了实际考试完成率。</p><p>员工号优先；姓名唯一时提供核对线索；重名保留人工判断。输出之后，仍由我核对。</p></section>`,right:`${image('ops-01.webp','SOP AI 工作台｜整体界面（合成数据）')}${image('ops-03.webp','异常编号并排核对｜保留人工判断')}${image('ops-02.webp','汇总报表｜输出后再核对')}${image('ops-04.webp','通报文案｜减少重复整理')}`};

